import { Pool } from 'pg';
import { Connection, Keypair, PublicKey, SystemProgram, Transaction } from '@solana/web3.js';
import { createMint, getOrCreateAssociatedTokenAccount, mintTo, transfer } from '@solana/spl-token';

function text(v){return String(v??'').trim();}
function secret(value){const raw=text(value);if(!raw)throw new Error('SOLANA_PAYER_SECRET_KEY is required.');const bytes=raw.startsWith('[')?Uint8Array.from(JSON.parse(raw)):Uint8Array.from(Buffer.from(raw,'base64'));return bytes.length===32?Keypair.fromSeed(bytes):Keypair.fromSecretKey(bytes);}
function positive(v,name){const n=Number(v);if(!Number.isFinite(n)||n<=0)throw new Error(`${name} must be greater than zero.`);return n;}
function units(value,decimals){const s=text(value);if(!/^\d+(?:\.\d+)?$/.test(s))throw new Error('Invalid token quantity.');const [w,f='']=s.split('.');if(f.length>decimals)throw new Error(`Quantity exceeds ${decimals} decimals.`);const result=BigInt(`${w}${f.padEnd(decimals,'0')}`);if(result<=0n)throw new Error('Quantity must be greater than zero.');return result;}
function lamports(value){const amount=units(value,9);if(amount>BigInt(Number.MAX_SAFE_INTEGER))throw new Error('amount is too large for a SOL transfer.');return Number(amount);}

export class SraTokenWorker{
  constructor(env=process.env){this.env=env;this.rpc=text(env.SOLANA_RPC_URL);this.db=text(env.DATABASE_URL||env.EXECUTOR_DATABASE_URL);this.pool=this.db?new Pool({connectionString:this.db}):null;this.payer=null;this.connection=null;}
  async initialize(){if(!this.rpc||!this.pool)throw new Error('Solana RPC and executor database are required.');this.payer=secret(this.env.SOLANA_PAYER_SECRET_KEY);this.connection=new Connection(this.rpc,'confirmed');await this.pool.query(`CREATE TABLE IF NOT EXISTS sra_token_chain_state (symbol TEXT PRIMARY KEY,mint_address TEXT NOT NULL,decimals INTEGER NOT NULL,authorized_supply NUMERIC NOT NULL,issued_supply NUMERIC NOT NULL,platform_token_account TEXT NOT NULL,mint_signature TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW())`);await this.pool.query(`CREATE TABLE IF NOT EXISTS sra_chain_transfers (transfer_id TEXT PRIMARY KEY,asset TEXT NOT NULL,destination_address TEXT NOT NULL,amount NUMERIC NOT NULL,transaction_signature TEXT,state TEXT NOT NULL,response_json JSONB,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW())`);}
  platformWallet(){return{network:'SOLANA',cluster:text(this.env.SOLANA_CLUSTER||'devnet'),address:this.payer.publicKey.toBase58()};}
  async state(){return(await this.pool.query(`SELECT * FROM sra_token_chain_state WHERE symbol='SRA'`)).rows[0]||null;}
  async transferRow(id){return(await this.pool.query('SELECT * FROM sra_chain_transfers WHERE transfer_id=$1',[id])).rows[0]||null;}
  async reconcileSubmitted(row){if(!row?.transaction_signature)return null;const status=(await this.connection.getSignatureStatuses([row.transaction_signature],{searchTransactionHistory:true})).value[0];if(status?.err)throw new Error(`Previously submitted Solana transaction ${row.transaction_signature} failed on chain.`);if(status?.confirmationStatus==='confirmed'||status?.confirmationStatus==='finalized'){const response={...(row.response_json||{}),transactionSignature:row.transaction_signature,state:'CONFIRMED'};await this.pool.query(`UPDATE sra_chain_transfers SET state='CONFIRMED',response_json=$2 WHERE transfer_id=$1`,[row.transfer_id,response]);return response;}return{...(row.response_json||{}),transactionSignature:row.transaction_signature,state:'SUBMITTED',confirmationPending:true};}
  async transferSol(input,id){if(text(input.transferId)!==id)throw new Error('Idempotency-Key must equal transferId.');const destinationAddress=text(input.destinationAddress),amount=text(input.amount);let destination;try{destination=new PublicKey(destinationAddress);}catch{throw new Error('destinationAddress is not a valid Solana address.');}const amountLamports=lamports(amount);const client=await this.pool.connect();try{await client.query('SELECT pg_advisory_lock(hashtext($1))',[id]);let row=(await client.query('SELECT * FROM sra_chain_transfers WHERE transfer_id=$1',[id])).rows[0];if(row&&(row.asset!=='SOL'||row.destination_address!==destination.toBase58()||text(row.amount)!==amount))throw new Error('transferId was already used with different transfer details.');if(row?.state==='CONFIRMED'&&row.response_json)return row.response_json;if(row?.transaction_signature)return await this.reconcileSubmitted(row);if(!row){await client.query(`INSERT INTO sra_chain_transfers(transfer_id,asset,destination_address,amount,state,response_json,created_at) VALUES($1,'SOL',$2,$3,'PREPARED',$4,NOW())`,[id,destination.toBase58(),amount,{transferId:id,asset:'SOL',fromAddress:this.payer.publicKey.toBase58(),destinationAddress:destination.toBase58(),amount}]);}
    const latest=await this.connection.getLatestBlockhash('confirmed');const tx=new Transaction({feePayer:this.payer.publicKey,recentBlockhash:latest.blockhash}).add(SystemProgram.transfer({fromPubkey:this.payer.publicKey,toPubkey:destination,lamports:amountLamports}));tx.sign(this.payer);const signature=await this.connection.sendRawTransaction(tx.serialize(),{skipPreflight:false,maxRetries:3});const submitted={transferId:id,asset:'SOL',fromAddress:this.payer.publicKey.toBase58(),destinationAddress:destination.toBase58(),amount,transactionSignature:signature,state:'SUBMITTED'};await client.query(`UPDATE sra_chain_transfers SET transaction_signature=$2,state='SUBMITTED',response_json=$3 WHERE transfer_id=$1`,[id,signature,submitted]);try{await this.connection.confirmTransaction({signature,blockhash:latest.blockhash,lastValidBlockHeight:latest.lastValidBlockHeight},'confirmed');const confirmed={...submitted,state:'CONFIRMED'};await client.query(`UPDATE sra_chain_transfers SET state='CONFIRMED',response_json=$2 WHERE transfer_id=$1`,[id,confirmed]);return confirmed;}catch(error){error.transactionSignature=signature;throw error;}
  }finally{await client.query('SELECT pg_advisory_unlock(hashtext($1))',[id]).catch(()=>{});client.release();}}
  async createSraMint(input,id){if(text(input.issuanceId)!==id)throw new Error('Idempotency-Key must equal issuanceId.');const authorizedSupply=positive(input.authorizedSupply,'authorizedSupply');const decimals=Number.isInteger(input.decimals)?input.decimals:8;const existing=await this.state();if(existing){if(Number(existing.authorized_supply)!==authorizedSupply)throw new Error('SRA mint already exists with a different authorized supply.');return{symbol:'SRA',mintAddress:existing.mint_address,platformTokenAccount:existing.platform_token_account,authorizedSupply:Number(existing.authorized_supply),issuedSupply:Number(existing.issued_supply),decimals:existing.decimals,state:'ACTIVE',existing:true};}const mint=await createMint(this.connection,this.payer,this.payer.publicKey,this.payer.publicKey,decimals);const account=await getOrCreateAssociatedTokenAccount(this.connection,this.payer,mint,this.payer.publicKey);const signature=await mintTo(this.connection,this.payer,mint,account.address,this.payer,units(input.authorizedSupply,decimals));await this.pool.query(`INSERT INTO sra_token_chain_state(symbol,mint_address,decimals,authorized_supply,issued_supply,platform_token_account,mint_signature) VALUES('SRA',$1,$2,$3,$3,$4,$5)`,[mint.toBase58(),decimals,input.authorizedSupply,account.address.toBase58(),signature]);return{symbol:'SRA',mintAddress:mint.toBase58(),platformTokenAccount:account.address.toBase58(),authorizedSupply:Number(input.authorizedSupply),issuedSupply:Number(input.authorizedSupply),decimals,transactionSignature:signature,state:'ACTIVE',existing:false};}
  async transferSra(input,id){if(text(input.transferId)!==id)throw new Error('Idempotency-Key must equal transferId.');const old=await this.transferRow(id);if(old?.response_json)return old.response_json;const amount=positive(input.amount,'amount');let owner;try{owner=new PublicKey(text(input.destinationAddress));}catch{throw new Error('destinationAddress is not a valid Solana address.');}const state=await this.state();if(!state)throw new Error('SRA has not been put on chain yet.');const mint=new PublicKey(state.mint_address);const destination=await getOrCreateAssociatedTokenAccount(this.connection,this.payer,mint,owner);const signature=await transfer(this.connection,this.payer,new PublicKey(state.platform_token_account),destination.address,this.payer,units(input.amount,state.decimals));const response={transferId:id,asset:'SRA',mintAddress:state.mint_address,fromAddress:this.payer.publicKey.toBase58(),destinationAddress:owner.toBase58(),amount,transactionSignature:signature,state:'CONFIRMED'};await this.pool.query(`INSERT INTO sra_chain_transfers VALUES($1,'SRA',$2,$3,$4,'CONFIRMED',$5,NOW())`,[id,owner.toBase58(),input.amount,signature,response]);return response;}
  async close(){await this.pool?.end();}
}
